 value=2
 class Box:
  def read(self):
   nonlocal value
   return lambda:value
  def write(self,n):
   nonlocal value
   value=n
 return Box()
box=make()
read=box.read()
box.write(9)
print(read())

class Box:
 def make(self):
  return [lambda:i for i in range(3)]
print([f() for f in Box().make()])

class Base:
 value=4
class Box(Base):
 def read(self,n):return super().value+n,__class__.__name__
print(Box().read(3))

class Box:
 def __init__(self,n):self._value=n
 @classmethod
 def make(cls):return cls(7)
 @staticmethod
 def twice(n):return 2*n
 @property
 def value(self):return self._value
 @value.setter
 def value(self,n):self._value=n
a=Box.make()
a.value=8
print(a.value,Box.twice(3))

events=[]
def mark(name):
 events.append(name)
 return name
def decorate(fn):
 events.append(('decorate',fn.__annotations__))
 return fn
class Box:
 @decorate
 def run(self,a:mark('annotation')=mark('default'))->mark('return'):return a
print(Box().run(),events)

class Box:
 def run(self):return 2
box=Box()
old=box.run
def replacement(self):return 9
Box.run=replacement
print(old(),box.run())
del Box.run
try:box.run()
except AttributeError:print('missing')

